variables.pick:
{%- macro norm(s) -%}{{ s | lower | regex_replace('[^a-z0-9 ]', ' ') | regex_replace('\s+', ' ') | trim }}{%- endmacro -%}
{%- set qn = norm(name) -%}
{%- set ns = namespace(best=none, score=0) -%}
{%- for p in lib['items'] -%}
  {%- set n = norm(p.name) -%}
  {%- set words = qn.split(' ') -%}
  {%- set hits = words | select('in', n.split(' ')) | list | count -%}
  {%- set s = 100 if n == qn else 80 if (n.startswith(qn) or qn.startswith(n)) and n|length > 2 else 60 if qn in n else (40 * hits / words|count) if hits == words|count else 0 -%}
  {%- if s > ns.score -%}{%- set ns.best = p -%}{%- set ns.score = s -%}{%- endif -%}
{%- endfor -%}
{{ {'uri': ns.best.uri, 'name': ns.best.name | trim} if ns.best and (kind == 'playlist' or ns.score >= 100) else {} }}

{%- macro norm(s) -%}{{ s | lower | regex_replace('^the ', '') | regex_replace('[^a-z0-9 ]', ' ') | regex_replace('\s+', ' ') | trim }}{%- endmacro -%}
{%- set qn = norm(name) -%}
{%- set A = res.artists | default([]) -%}{%- set T = res.tracks | default([]) -%}{%- set L = res.albums | default([]) -%}{%- set P = res.playlists | default([]) -%}
{%- macro track(t) -%}{{ t.name }}{% set a = t.artists | default([]) | map(attribute='name') | list %}{{ ' by ' ~ a[0] if a else '' }}{%- endmacro -%}
{%- if kind == 'track' and T -%}{{ {'uri': T[0].uri, 'name': track(T[0])} }}
{%- elif kind == 'artist' and A -%}{{ {'uri': A[0].uri, 'name': A[0].name} }}
{%- elif kind == 'playlist' and P -%}{{ {'uri': P[0].uri, 'name': 'the ' ~ P[0].name ~ ' playlist'} }}
{%- elif kind == 'any' and A and norm(A[0].name) == qn -%}{{ {'uri': A[0].uri, 'name': A[0].name} }}
{%- elif kind == 'any' and T and norm(T[0].name) == qn -%}{{ {'uri': T[0].uri, 'name': track(T[0])} }}
{%- elif kind == 'any' and L and norm(L[0].name) == qn -%}{{ {'uri': L[0].uri, 'name': L[0].name} }}
{%- elif kind == 'any' and A -%}{{ {'uri': A[0].uri, 'name': A[0].name} }}
{%- elif kind == 'any' and T -%}{{ {'uri': T[0].uri, 'name': track(T[0])} }}
{%- else -%}{}{%- endif -%}

